#include <algorithm>
#include <cassert>
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <string>
#include <vector>

/// @brief 应用层缓冲区，解决 TCP 粘包/拆包问题
///
/// 内存布局：
/// +-------------------+------------------+------------------+
/// | prepend (8 bytes) | readable region  | writable region  |
/// +-------------------+------------------+------------------+
/// ^                   ^                  ^                  ^
/// 0               reader_index_     writer_index_       size()
class Buffer {
 public:
  static constexpr size_t kCheapPrepend = 8;   // 预留空间（用于添加长度头等）
  static constexpr size_t kInitialSize = 1024;  // 默认初始大小

  explicit Buffer(size_t initial_size = kInitialSize)
      : buffer_(kCheapPrepend + initial_size),
        reader_index_(kCheapPrepend),
        writer_index_(kCheapPrepend) {}

  /// 可读字节数
  size_t readableBytes() const { return writer_index_ - reader_index_; }

  /// 可写字节数
  size_t writableBytes() const { return buffer_.size() - writer_index_; }

  /// 预留区域已使用字节数
  size_t prependableBytes() const { return reader_index_; }

  /// 返回可读数据的起始指针
  const char* peek() const { return begin() + reader_index_; }

  /// 查找 CRLF 分隔符（HTTP 协议用）
  const char* findCRLF() const {
    const char* crlf = std::search(peek(), beginWritable(), kCRLF, kCRLF + 2);
    return crlf == beginWritable() ? nullptr : crlf;
  }

  /// 读取 len 字节到 string
  std::string retrieveAsString(size_t len) {
    assert(len <= readableBytes());
    std::string result(peek(), len);
    retrieve(len);
    return result;
  }

  /// 读取所有可读数据到 string
  std::string retrieveAllAsString() {
    return retrieveAsString(readableBytes());
  }

  /// 读取所有可读数据到 vector<char>
  std::vector<char> retrieveAll() {
    std::vector<char> result(peek(), beginWritable());
    retrieveAllInternal();
    return result;
  }

  /// 移动读指针
  void retrieve(size_t len) {
    assert(len <= readableBytes());
    if (len < readableBytes()) {
      reader_index_ += len;
    } else {
      retrieveAllInternal();
    }
  }

  /// 确保有足够的可写空间
  void ensureWritableBytes(size_t len) {
    if (writableBytes() < len) {
      makeSpace(len);
    }
    assert(writableBytes() >= len);
  }

  /// 向缓冲区追加数据
  void append(const char* data, size_t len) {
    ensureWritableBytes(len);
    std::copy(data, data + len, beginWritable());
    writer_index_ += len;
  }

  void append(const std::string& str) { append(str.data(), str.size()); }

  /// 在预留空间添加数据（用于封装协议头）
  void prepend(const void* data, size_t len) {
    assert(len <= prependableBytes());
    reader_index_ -= len;
    const char* d = static_cast<const char*>(data);
    std::copy(d, d + len, begin() + reader_index_);
  }

  /// 从 fd 读取数据到缓冲区
  ssize_t readFromFd(int fd, int* saved_errno);

  char* beginWrite() { return begin() + writer_index_; }
  const char* beginWrite() const { return begin() + writer_index_; }
  const char* beginWritable() const { return begin() + writer_index_; }

 private:
  char* begin() { return &*buffer_.begin(); }
  const char* begin() const { return &*buffer_.begin(); }

  void retrieveAllInternal() {
    reader_index_ = kCheapPrepend;
    writer_index_ = kCheapPrepend;
  }

  /// 扩容
  void makeSpace(size_t len) {
    if (writableBytes() + prependableBytes() < len + kCheapPrepend) {
      buffer_.resize(writer_index_ + len);
    } else {
      // 把可读数据挪到前面，回收空间
      size_t readable = readableBytes();
      std::copy(begin() + reader_index_, begin() + writer_index_,
                begin() + kCheapPrepend);
      reader_index_ = kCheapPrepend;
      writer_index_ = reader_index_ + readable;
    }
  }

  static constexpr char kCRLF[] = "\r\n";

  std::vector<char> buffer_;
  size_t reader_index_;
  size_t writer_index_;
};", "old_string": ""}

