#include <cstdint>
#include <functional>
#include <memory>
#include <sys/epoll.h>

class EventLoop;

/// @brief 对文件描述符的封装，绑定事件回调
///
/// Channel 不拥有 fd，它只是 fd 的事件分发器。
/// 每个 Channel 对应一个 fd，负责注册/处理 IO 事件。
class Channel {
 public:
  using EventCallback = std::function<void()>;

  Channel(EventLoop* loop, int fd);
  ~Channel();

  /// 处理事件（由 EventLoop 调用）
  void handleEvent();

  /// 设置回调
  void setReadCallback(EventCallback cb) { read_callback_ = std::move(cb); }
  void setWriteCallback(EventCallback cb) { write_callback_ = std::move(cb); }
  void setCloseCallback(EventCallback cb) { close_callback_ = std::move(cb); }
  void setErrorCallback(EventCallback cb) { error_callback_ = std::move(cb); }

  int fd() const { return fd_; }
  uint32_t events() const { return events_; }
  void setRevents(uint32_t revt) { revents_ = revt; }
  bool isNoneEvent() const { return events_ == kNoneEvent; }

  /// 注册/注销读事件
  void enableReading() {
    events_ |= kReadEvent;
    update();
  }
  void disableReading() {
    events_ &= ~kReadEvent;
    update();
  }

  /// 注册/注销写事件
  void enableWriting() {
    events_ |= kWriteEvent;
    update();
  }
  void disableWriting() {
    events_ &= ~kWriteEvent;
    update();
  }

  /// 禁用所有事件
  void disableAll() {
    events_ = kNoneEvent;
    update();
  }

  bool isWriting() const { return events_ & kWriteEvent; }
  bool isReading() const { return events_ & kReadEvent; }

  /// 从 EventLoop 中移除
  void remove();

 private:
  void update();

  static constexpr uint32_t kNoneEvent = 0;
  static constexpr uint32_t kReadEvent = EPOLLIN | EPOLLPRI;
  static constexpr uint32_t kWriteEvent = EPOLLOUT;

  EventLoop* owner_loop_;
  const int fd_;
  uint32_t events_;
  uint32_t revents_;

  EventCallback read_callback_;
  EventCallback write_callback_;
  EventCallback close_callback_;
  EventCallback error_callback_;
};", "old_string": ""}

