#include <atomic>
#include <cstdint>
#include <functional>
#include <memory>
#include <mutex>
#include <vector>
#include <sys/epoll.h>

class Channel;

/// @brief Reactor 核心 —— 事件循环
///
/// 单线程事件驱动模型：
///   1. 调用 epoll_wait 等待事件
///   2. 遍历活跃 Channel，分发事件回调
///   3. 执行待处理的 functor（跨线程调用队列）
class EventLoop {
 public:
  using Functor = std::function<void()>;

  EventLoop();
  ~EventLoop();

  /// 开始事件循环（阻塞）
  void loop();

  /// 退出事件循环
  void quit();

  /// 在 IO 线程中执行回调
  void runInLoop(Functor cb);

  /// 将回调放入队列，唤醒 IO 线程
  void queueInLoop(Functor cb);

  /// Channel 操作
  void updateChannel(Channel* channel);
  void removeChannel(Channel* channel);

  /// 是否在 IO 线程中
  bool isInLoopThread() const;

 private:
  void wakeup();                        // 唤醒 epoll_wait
  void handleRead();                    // 处理 wakeup fd
  void doPendingFunctors();             // 执行待处理回调

  static constexpr int kInitEventListSize = 16;

  int epoll_fd_;
  int wakeup_fd_;
  std::unique_ptr<Channel> wakeup_channel_;

  std::atomic<bool> looping_;
  std::atomic<bool> quit_;
  std::atomic<bool> calling_pending_functors_;

  std::vector<struct epoll_event> events_;
  std::vector<Channel*> active_channels_;

  std::mutex mutex_;
  std::vector<Functor> pending_functors_;
};", "old_string": ""}

