#include "Buffer.h"

#include <any>
#include <atomic>
#include <functional>
#include <memory>
#include <string>

class Channel;
class EventLoop;

/// @brief TCP 连接的封装
///
/// 生命周期由 shared_ptr 管理，防止断开后悬空引用。
/// 每个 TcpConnection 持有一个 Channel，绑定到 EventLoop。
class TcpConnection : public std::enable_shared_from_this<TcpConnection> {
 public:
  using TcpConnectionPtr = std::shared_ptr<TcpConnection>;
  using ConnectionCallback = std::function<void(const TcpConnectionPtr&)>;
  using MessageCallback = std::function<void(const TcpConnectionPtr&, Buffer*)>;
  using CloseCallback = std::function<void(const TcpConnectionPtr&)>;

  TcpConnection(EventLoop* loop, const std::string& name, int sockfd);
  ~TcpConnection();

  EventLoop* getLoop() const { return loop_; }
  const std::string& name() const { return name_; }
  int fd() const { return channel_->fd(); }

  /// 发送数据（线程安全）
  void send(const std::string& message);
  void send(const char* data, size_t len);

  /// 主动关闭连接
  void shutdown();

  /// 连接建立后调用
  void connectionEstablished();

  /// 连接销毁前调用
  void connectionDestroyed();

  /// 设置回调
  void setConnectionCallback(ConnectionCallback cb) {
    connection_callback_ = std::move(cb);
  }
  void setMessageCallback(MessageCallback cb) {
    message_callback_ = std::move(cb);
  }
  void setCloseCallback(CloseCallback cb) {
    close_callback_ = std::move(cb);
  }

  /// 用户上下文（用于存储用户名等业务数据）
  void setContext(const std::any& ctx) { context_ = ctx; }
  std::any& getContext() { return context_; }
  const std::any& getContext() const { return context_; }

  /// 获取输入缓冲区（用于 Codec 解析）
  Buffer* getInputBuffer() { return &input_buffer_; }

  bool connected() const { return state_ == kConnected; }

 private:
  enum State { kDisconnected, kConnecting, kConnected, kDisconnecting };

  void handleRead();
  void handleWrite();
  void handleClose();
  void handleError();

  void sendInLoop(const char* data, size_t len);

  EventLoop* loop_;
  std::string name_;
  std::atomic<State> state_;
  std::unique_ptr<Channel> channel_;

  Buffer input_buffer_;
  Buffer output_buffer_;

  ConnectionCallback connection_callback_;
  MessageCallback message_callback_;
  CloseCallback close_callback_;

  std::any context_;
};", "old_string": ""}
